exercise.solution_path:
Schaltungsvereinfachung:

![Abbildung zur Aufgabe et1-03-026-schaltungsberechnung_mit_zweipolersatzschaltung-1: Schaltungsberechnung mit Zweipolersatzschaltung 1 w1](assets/et1-03-026-schaltungsberechnung_mit_zweipolersatzschaltung-1/02-Schaltungsberechnung_mit_Zweipolersatzschaltung_1_w1.png)

\begin{align*}
U_{L1} &= U_{q1} \frac{R_3}{R_1 + R_2 + R_3}=\frac{1}{3}U_\mathrm{q}=3,\bar{3}\mathrm{V}

R_{i1} &= R_3 \Vert (R_1 + R_2)=\frac{2}{3}R=6,\bar{6}\Omega

U_{L3} &= \frac{(I_q R_9 + U_{q3})(R_7 \Vert (R_5 + R_6))}{R_8 + R_9 + R_7 \Vert (R_5 + R_6)} \cdot \frac{R_5}{R_5 + R_6}

&=\frac{(I_q R_9 + U_{q3})R_5R_7}{(R_5 + R_6+ R_7)(R_8 + R_9)+(R_5 + R_6)R_7}

&= \frac{U_q+I_q R}{8}=5\mathrm{V}

R_{i3} &= R_5 \Vert (R_6 + R_7 \Vert (R_8 + R_9))=R\Vert \left(R+\frac{2}{3}R\right)=\frac{5}{8}R=6,25\Omega
\end{align*}

\begin{align*}
I_X &= \frac{U_{L1} + U_{L3} - U_{q2}}{R_{i1} + R_{i3} + R_4}=\frac{\frac{U_q}{3}+\frac{U_q+I_q R}{8}-U_q}{(\frac{2}{3}+\frac{5}{8}+1)R}=\frac{-13U_q+3I_q R}{55R}

&=-\frac{4}{55}\mathrm{A}=-0,0\overline{72}\mathrm{A} \approx \underline{-72,7\mathrm{mA}}
\end{align*}
